package main

import (
	"bufio"
	"fmt"
	"os"
)

const INF int64 = 1<<60

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}

	// dp[i][j] = minimal triangulation weight for polygon from i to j (inclusive)
	dp := make([][]int64, n+1)
	for i := range dp {
		dp[i] = make([]int64, n+1)
		for j := range dp[i] {
			dp[i][j] = 0
		}
	}

	// length is the number of vertices in subpolygon
	for length := 3; length <= n; length++ {
		for i := 1; i+length-1 <= n; i++ {
			j := i + length - 1
			dp[i][j] = INF
			for k := i + 1; k < j; k++ {
				tri := int64(i) * int64(k) * int64(j)
				cost := dp[i][k] + dp[k][j] + tri
				if cost < dp[i][j] {
					dp[i][j] = cost
				}
			}
		}
	}

	fmt.Println(dp[1][n])
}
