	for length := 3; length <= n; length++ {
		for i := 1; i+length-1 <= n; i++ {
			j := i + length - 1
			// try all possible k as the third vertex of triangle (i, k, j)
			for k := i + 1; k < j; k++ {
				cost := dp[i][k] + dp[k][j] + int64(i*k*j)
				if cost < dp[i][j] {
					dp[i][j] = cost
				}
			}
		}
	}

	fmt.Println(dp[1][n])
